// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 unlockTime, uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        (uint256 storedUnlockTime, uint256 storedBalance) = c.Acc(actor);
        assertTrue(
            storedUnlockTime >= block.timestamp && storedBalance == amount,
            "Put must clamp unlockTime to at least now and credit the balance"
        );
    }
}
